\set ON_ERROR_STOP on
SELECT migration_test.ok('Catalog source aliases indexed without activation',(SELECT count(*)=11 FROM catalog.aliases) AND NOT EXISTS(SELECT 1 FROM catalog.deployment_heads WHERE active));
SELECT migration_test.ok('All new tables have forced row security',NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN('catalog','practice_private') AND c.relkind='r' AND(NOT c.relrowsecurity OR NOT c.relforcerowsecurity)));
SELECT migration_test.ok('Public metadata is opt-in unavailable listing',(SELECT count(*)=11 FROM catalog_api.exercises(true,100)) AND(SELECT count(*)=0 FROM catalog_api.exercises(false,100)));
SELECT migration_test.actor_ok('Unauthenticated Auth context sees no private sessions',NULL,'SELECT count(*)=0 FROM catalog_api.my_sessions(100)');
SELECT migration_test.actor_ok('Account A reads only its own session rows','11111111-1111-4111-8111-111111111111','SELECT count(*)=2 FROM catalog_api.my_sessions(100)');
SELECT migration_test.actor_ok('Account B cannot read account A session','22222222-2222-4222-8222-222222222222',$q$SELECT count(*)=0 FROM catalog_api.my_sessions(100) WHERE id='cccccccc-cccc-4ccc-8ccc-ccccccccccc1'$q$);
SELECT migration_test.reject('Authenticated role cannot select renderer seeds',$q$SET LOCAL ROLE authenticated;SELECT seed FROM practice_private.renderer_state$q$,'42501');
SELECT migration_test.reject('Authenticated role cannot select even owned raw scores',$q$SET LOCAL ROLE authenticated;SELECT score FROM practice_private.attempts$q$,'42501');
SELECT migration_test.reject('Anonymous role cannot execute owner RPC',$q$SET LOCAL ROLE anon;SELECT * FROM catalog_api.my_sessions()$q$,'42501');
SELECT migration_test.ok('Browser roles have no membership in reader role',NOT pg_has_role('authenticated','practice_api_reader','MEMBER') AND NOT pg_has_role('anon','practice_api_reader','MEMBER'));
SELECT migration_test.reject('Browser cannot call backend claim function',$q$SET LOCAL ROLE authenticated;SELECT practice_private.claim_guest(NULL,NULL,NULL,NULL)$q$,'42501');
SELECT migration_test.reject('Reader role cannot read private tokens',$q$SET LOCAL ROLE practice_api_reader;SELECT session_token FROM practice_private.renderer_state$q$,'42501');
SELECT migration_test.ok('Reader role has no superuser, login or RLS bypass',EXISTS(SELECT 1 FROM pg_roles WHERE rolname='practice_api_reader' AND NOT rolcanlogin AND NOT rolsuper AND NOT rolbypassrls AND NOT rolinherit));
SELECT migration_test.ok('No new function is executable by PUBLIC',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname IN('catalog','practice_private','catalog_api') AND a.grantee=0 AND a.privilege_type='EXECUTE'));
SELECT migration_test.ok('All definer functions pin their search path',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('catalog','practice_private','catalog_api') AND p.prosecdef AND NOT('search_path=pg_catalog'=ANY(coalesce(p.proconfig,ARRAY[]::text[])))));
SELECT migration_test.ok('Complete synthetic evidence passes strict eligibility',catalog.assessment_is_eligible(migration_test.ref('assessment')));
SELECT migration_test.reject('Sealed profile dimensions cannot be changed',$q$INSERT INTO catalog.profile_dimensions VALUES(migration_test.ref('profile'),99,'desktop')$q$,'55000');
SELECT migration_test.reject('Closed verification runs cannot gain cases',$q$INSERT INTO catalog.case_attempts(run_id,source_version_id,requirement_set_id,environment_id,profile_id,seed,viewport,ordinal,state,source_verified,checks,correct_score,cleared_score) VALUES(migration_test.ref('run'),migration_test.ref('source'),migration_test.ref('requirement'),migration_test.ref('environment'),migration_test.ref('profile'),1234,'desktop',2,'passed',true,'{}',1,0)$q$,'55000');
