SELECT migration_test.actor_ok('Owner ordered answers restore without flattening choices','11111111-1111-4111-8111-111111111111',$q$SELECT answers->0->>1=' first ' AND answers->0->>0=answers->1->>0 FROM catalog_api.my_attempts('cccccccc-cccc-4ccc-8ccc-ccccccccccc1')$q$);
