SELECT migration_test.ok('Rejected feedback rolls back token, attempt and operation changes',(SELECT state='in-flight' FROM practice_private.submission_operations WHERE id=migration_test.ref('bad-feedback-operation')) AND(SELECT generation=1 FROM practice_private.sessions WHERE id='cccccccc-cccc-4ccc-8ccc-ccccccccccc1') AND(SELECT generation=1 AND session_token=decode('01','hex') FROM practice_private.renderer_state WHERE session_id='cccccccc-cccc-4ccc-8ccc-ccccccccccc1') AND(SELECT count(*)=1 FROM practice_private.attempts));
